p=Path(__file__).parent
d=json.loads((p/'phase1_source_spectral_mixer_probe.json').read_text(encoding='utf8'))
assert d['selected']['kind']=='spectral_mixer' and d['student_state'] is not None
payload={k:d[k] for k in ('selected','student_state','feature_mean','feature_std','heldout','heldout_clean_teacher_net')}
inner="\nfrom pathlib import Path\nimport hashlib,json,sys,numpy as np,torch\nfrom torch import nn\nfrom torch.nn import functional as F\nfrom experiments.pamf_phase1_flow import experiment as core,physical_rich_router_experiment as g,feature_conditioned_experiment as fs\nroot=Path('/home/szu2070436088/2510044040/CV-SincNet');torch.set_num_threads(2)\nmodels=g.load_models(root,'cpu');teacher,contract,dura,boundary,feature,_,_,_=models\ncache,clean,roles=core.data(root,contract)\nfrom leo_practical.channel import Config,receiver_for_session,stable_seed,normalize_input\nfrom leo_practical.residual import ResidualChannel\nids=np.load(cache/'train/physical_ids.npy',allow_pickle=False);rx=np.load(cache/'train/rx.npy',allow_pickle=False);day=np.load(cache/'train/day.npy',allow_pickle=False)\ngroups=[]\nfor role,count,initial,n in (('L_s',6300,128,1024),('U_s',56700,384,3072)):\n available=np.flatnonzero(roles==role);prior=available[np.linspace(0,count-1,initial,dtype=int)];available=np.setdiff1d(available,prior,assume_unique=True)\n for _ in range(3):\n  old=available[np.linspace(0,len(available)-1,n,dtype=int)];available=np.setdiff1d(available,old,assume_unique=True)\n take=128 if role=='L_s' else 384;prior=available[np.linspace(0,len(available)-1,take,dtype=int)];available=np.setdiff1d(available,prior,assume_unique=True)\n for _ in range(2):\n  old=available[np.linspace(0,len(available)-1,n,dtype=int)];available=np.setdiff1d(available,old,assume_unique=True)\n take=64 if role=='L_s' else 192;prior=available[np.linspace(0,len(available)-1,take,dtype=int)];available=np.setdiff1d(available,prior,assume_unique=True)\n take=512 if role=='L_s' else 1536;groups.append(available[np.linspace(0,len(available)-1,take,dtype=int)])\nfixed=np.concatenate(groups);assert len(fixed)==len(np.unique(fixed))==2048\norder=np.random.default_rng(2026110261).permutation(len(fixed));split=np.empty(len(fixed),dtype=np.int64)\nsplit[order[:1228]]=0;split[order[1228:1638]]=1;split[order[1638:]]=2\nassert [int((split==i).sum()) for i in range(3)]==[1228,410,410]\nfixed=fixed[np.sort(order[1638:])];assert len(fixed)==410\nview_names=('clean','practical_low_suburban','practical_mid_urban','practical_low_urban');namespace='phase1-source-convex-student-2026110262';views={}\nwith torch.no_grad():\n for view in view_names:\n  if view=='clean':received=np.asarray(clean[fixed],dtype=np.float32)\n  else:\n   cfg=Config(fs_hz=25e6,fc_hz=2462e6,scenario=view,processing_route='residual',mode='post_sync',equalization_enabled=False,reference_snr_db=30.,boundary='reflect')\n   received=[]\n   for j in fixed:\n    pid=str(ids[j]);session='rx%d:day%d:eq1'%(int(rx[j]),int(day[j]));hw=receiver_for_session(cfg,2026110265,session)\n    v=np.asarray(clean[j],dtype=np.float64);signal,_=normalize_input(v[0]+1j*v[1]);result,meta=ResidualChannel(cfg,stable_seed(2026110262,namespace,view,pid),hw).process(signal)\n    assert np.isfinite(result).all() and not meta['channel_equalization_applied'];received.append(np.stack((result.real,result.imag)).astype(np.float32))\n   received=np.stack(received)\n  obs={k:[] for k in ('signals','probs','features')}\n  for start in range(0,len(fixed),32):\n   x=core.tensor(received[start:start+32],'cpu');anchor=dura(x);fa=teacher.features(anchor);base=teacher.classify_features(fa)\n   outputs=(x,anchor,boundary(x,anchor),feature(x,anchor,fa,base));signals=torch.stack(outputs,dim=1)\n   rawfeat=teacher.features(x);logits=(teacher.classify_features(rawfeat),base,teacher.classify_features(teacher.features(outputs[2])),teacher.classify_features(teacher.features(outputs[3])))\n   probs=torch.stack([F.softmax(z,dim=1) for z in logits],dim=1)\n   energy=torch.stack((x.square().mean((1,2)).clamp_min(1e-8).log(),anchor.square().mean((1,2)).clamp_min(1e-8).log()),1)\n   def spectrum(z):\n    wave=torch.complex(z[:,0,:],z[:,1,:]);power=torch.fft.fft(wave,dim=-1).abs().square().reshape(len(z),16,16).mean(-1)\n    return power/power.sum(1,keepdim=True).clamp_min(1e-8)\n   feats=torch.cat((probs.reshape(len(x),24),energy,F.normalize(rawfeat,dim=1),F.normalize(fa,dim=1),spectrum(x),spectrum(x-anchor)),1)\n   assert feats.shape==(len(x),378) and torch.isfinite(feats).all()\n   obs['signals'].append(signals.cpu());obs['probs'].append(probs.cpu());obs['features'].append(feats.cpu())\n  views[view]={k:torch.cat(v) for k,v in obs.items()};print('SPECTRAL_MIXER_SOURCE_EXPERTS_FIXED',view,flush=True)\nprint('ALL_SOURCE_EXPERTS_FIXED_BEFORE_SOURCE_LABELS',flush=True)\n\nexpected=json.load(sys.stdin)\nlabels=fs.source_labels(root,cache,clean,roles,contract);labeled=roles[fixed]=='L_s';assert np.all(labels[fixed[~labeled]]==-1)\nref=np.from_dlpack(views['clean']['probs'][:,0,:]);teacher_ref=ref.argmax(1);valid=labeled|(ref.max(1)>=.95);target=np.where(labeled,labels[fixed],teacher_ref)\nstudent=nn.Sequential(nn.Linear(378,128),nn.GELU(),nn.Linear(128,64))\nstudent.load_state_dict({k:torch.tensor(v,dtype=torch.float32) for k,v in expected['student_state'].items()},strict=True);student.eval()\nmean=np.asarray(expected['feature_mean'],dtype=np.float32);std=np.asarray(expected['feature_std'],dtype=np.float32);alpha=expected['selected']['alpha'];results={}\nclean_net=None\nwith torch.no_grad():\n for view in view_names:\n  v=views[view];features=np.from_dlpack(v['features']);scaled=np.clip((features-mean)/std,-10,10).astype(np.float32)\n  outputs=[]\n  for start in range(0,len(fixed),128):\n   signals=v['signals'][start:start+128];w=F.softmax(student(core.tensor(scaled[start:start+128],'cpu')).reshape(-1,4,16),1)\n   z=torch.complex(signals[:,:,0,:],signals[:,:,1,:]);spectrum=torch.fft.fft(z,dim=-1)\n   mixed=(spectrum*w.repeat_interleave(16,dim=2)).sum(dim=1);z=torch.fft.ifft(mixed,dim=-1)\n   mix=torch.stack((z.real,z.imag),dim=1);wave=signals[:,1]+alpha*(mix-signals[:,1])\n   outputs.append(teacher.classify_features(teacher.features(wave)).argmax(1).cpu())\n  output=np.from_dlpack(torch.cat(outputs));pred=np.from_dlpack(v['probs']).argmax(2);old=pred[:,1]==target;new=output==target;lm=valid&labeled\n  row=dict(valid_count=int(valid.sum()),L_s_count=int(lm.sum()),U_confident_count=int((valid&~labeled).sum()),\n   baseline=int((valid&old).sum()),student=int((valid&new).sum()),repairs=int((valid&~old&new).sum()),damages=int((valid&old&~new).sum()),\n   L_s_baseline=int((lm&old).sum()),L_s_student=int((lm&new).sum()))\n  assert row==expected['heldout'][view],(view,row,expected['heldout'][view]);results[view]=row\n  if view=='clean':clean_net=int((output==teacher_ref).sum()-(pred[:,1]==teacher_ref).sum())\nassert clean_net==expected['heldout_clean_teacher_net']\nprint('SPECTRAL_MIXER_REPLAY '+json.dumps(dict(status='VERIFIED_SOURCE_SPECTRAL_MIXER_REPLAY',heldout_ids=len(fixed),views=results,\n clean_teacher_net=clean_net,models_refit=0,U_s_labels_read=0,V_reads=0,test_IQ_reads=0,\n caveat='Fixed experts saw source records; targets mix L_s true labels and confident U_s teacher pseudo-labels. Simulator is not validated real satellite data.'),ensure_ascii=False),flush=True)\n"
remote="from pathlib import Path\nimport os,subprocess\nroot=Path('/home/szu2070436088/2510044040/CV-SincNet');run='20261101-phase1-physical-rich-router-s2026092701-r01'\nrelease=root/'releases'/(run+'-release');native=root/'releases/20261027-phase1-pamf-repl-shuffled-views-m16-r02-release'\nassert (release/'release_commit.txt').read_text().strip()=='b7beba9e6419a1ec4bf39c83cc17e2ee6478d5f0'\nenv=dict(os.environ,PYTHONPATH=':'.join(map(str,(release,native))),CUDA_VISIBLE_DEVICES='',OMP_NUM_THREADS='2',MKL_NUM_THREADS='2',OPENBLAS_NUM_THREADS='2')\ninner=__INNER__;payload=__PAYLOAD__\nsubprocess.run(['/home/szu2070436088/.conda/envs/CVS-RFFI/bin/python','-u','-c',inner],cwd=release,env=env,input=payload,text=True,check=True,timeout=900)\n"
